// ❌ OLD: A scroll listener that reads geometry on every event forces
// a SYNCHRONOUS LAYOUT (reflow) each time. Because scroll fires at
// high frequency, this janks the page and burns main-thread time —
// especially with many observed elements.
window.addEventListener('scroll', () => {
  // ❌ OLD: getBoundingClientRect forces layout synchronously
  const r = el.getBoundingClientRect();
  if (r.top < window.innerHeight) {
    loadContent();
    window.removeEventListener('scroll', handler);
  }
});

// The handler runs on every scroll tick even when the element is far
// off-screen — O(N) geometry reads per frame.

// ✅ NEW: IntersectionObserver computes intersection asynchronously
// (off the main-thread scroll path) and only fires the callback when a
// configured threshold is crossed — not on every pixel of scroll.
const io = new IntersectionObserver(
  (entries) => {
    if (entries[0].isIntersecting) {
      loadContent();
      io.disconnect(); // stop observing once loaded
    }
  },
  { rootMargin: '200px' } // ✅ NEW: pre-load before the element enters
);

io.observe(el); // ✅ NEW: observe once; the engine does the rest

